function digest(commit, baseDigest) {
  // toy content-address: identity = code commit + resolved base image
  return 'sha256:' + commit + '-' + baseDigest;
}
function build(commit, baseTagState) {
  // a build resolves the floating base tag to whatever it points at NOW
  return digest(commit, baseTagState.node22);
}

var commit = 'c0ffee';
var baseTag = { node22: 'A' };            // node:22 currently resolves to digest A

// BUILD-ONCE + PROMOTE: build a single image, reuse the SAME digest everywhere
var artifact = build(commit, baseTag);
function promote(env, img) { return env + ' runs ' + img; }

// REBUILD-PER-ENV: staging builds now; prod rebuilds later, after the base tag moved
var stagingImg = build(commit, baseTag);
baseTag.node22 = 'B';                      // node:22 re-pushed for an OS patch -> digest B
var prodImg = build(commit, baseTag);

console.log('PROMOTE (build once):');
console.log(promote('staging', artifact));
console.log(promote('prod', artifact));
console.log('identical=' + (artifact === artifact));
console.log('REBUILD PER ENV:');
console.log(promote('staging', stagingImg));
console.log(promote('prod', prodImg));
console.log('identical=' + (stagingImg === prodImg) + ' gitDiff=empty');
